#include "DisplayManager.h"

static uint16_t getMessageHeight(const DisplayMessage& msg)
{
    uint8_t textLines = (msg.text.length() + MAX_TEXT_LEN - 1) / MAX_TEXT_LEN;

    if(textLines == 0)
    {
        textLines = 1;
    }

    // Header      10 pixels
    // Text        10 pixels per line
    // Spacer      2 ixels

    return 10 + (textLines * 10) + 2;
}

DisplayManager::DisplayManager()
{
    wifiConnected   = false;
    dapnetConnected = false;
    clockString     = "--:--.--";
    ipAddress       = "---.---.---.---";
    messageCount    = 0;
    statusDirty     = true;
    messagesDirty   = true;
    fullRedraw      = true;
    whitelistCount = 0;

}

DisplayManager::~DisplayManager()
{
    // Nothing to destruct
}

void DisplayManager::begin()
{
    tft.init();

    // Landscape
    tft.setRotation(1);

    tft.fillScreen(TFT_BLACK);
    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.setTextDatum(TL_DATUM);
    tft.setTextWrap(false);

    redraw();

    Serial.println("Display initialized.");

}

void DisplayManager::loop()
{
    if( fullRedraw )
    {
        redraw();
        return;
    }

    if( messagesDirty )
    {
        drawMessages();
        messagesDirty = false;
    }

    if( statusDirty )
    {
        drawStatusBar();
        statusDirty = false;
    }
    
}

void DisplayManager::redraw()
{
    drawLayout();
    drawHeader();
    drawMessages();
    drawStatusBar();
    
    fullRedraw    = false;
    messagesDirty = false;
    statusDirty   = false;
    
}

void DisplayManager::setWifiStatus(bool connected)
{
    if( wifiConnected == connected )
    {
        return;
    }

    wifiConnected = connected;
    statusDirty = true;
    
}

void DisplayManager::setDapnetStatus(bool connected)
{
    if( dapnetConnected == connected )
    {
        return;
    }

    dapnetConnected = connected;
    statusDirty = true;
    
}

void DisplayManager::setClock(const String& timeString)
{
    if( clockString == timeString )
    {
        return;
    }

    clockString = timeString;
    statusDirty = true;
    
}

void DisplayManager::setIPAddress(const String& ip)
{
    if( ipAddress == ip )
    {
        return;
    }

    ipAddress = ip;
    statusDirty = true;
}

void DisplayManager::addMessage(uint32_t ric, uint8_t function, const String& name, const String& text)
{
    if( messageCount >= DISPLAY_MESSAGE_COUNT )
    {
        scrollMessages();
    }

    messages[messageCount].ric      = ric;
    messages[messageCount].function = function;
    messages[messageCount].name     = name;
    messages[messageCount].text     = text;

    messageCount++;
    messagesDirty = true;
    
}

void DisplayManager::scrollMessages()
{
    for( uint8_t i = 1; i < DISPLAY_MESSAGE_COUNT; i++ )
    {
        messages[i - 1] = messages[i];
    }

    messageCount = DISPLAY_MESSAGE_COUNT - 1;

}

void DisplayManager::clearMessages()
{
    messageCount = 0;
    messagesDirty = true;

}

void DisplayManager::drawLayout()
{
    tft.fillScreen(TFT_BLACK);

    // Divider
    tft.drawFastHLine(0, MESSAGE_HEIGHT - 1, DISPLAY_WIDTH, TFT_WHITE);
    
}

void DisplayManager::drawHeader()
{
    tft.fillRect(0, 0, DISPLAY_WIDTH, 22, TFT_BLACK );
    tft.setTextColor(TFT_YELLOW, TFT_BLACK);
    tft.setTextSize(2);
    tft.setCursor(5, 4);
    tft.print("CYD DAPNET Monitor");
    
}

void DisplayManager::drawStatusBar()
{
    tft.fillRect(0, MESSAGE_HEIGHT, DISPLAY_WIDTH, STATUS_HEIGHT, TFT_BLACK);
    tft.setTextSize(1);

    // WLAN
    tft.setCursor(3, MESSAGE_HEIGHT + 7);

    if( wifiConnected )
    {
        tft.setTextColor(TFT_GREEN, TFT_BLACK);
        tft.print("* WLAN");

        // IP address
        tft.setTextColor(TFT_BLUE, TFT_BLACK);
        tft.setCursor(228, MESSAGE_HEIGHT + 7);
        tft.print(ipAddress);
    }
    else
    {
        tft.setTextColor(TFT_RED, TFT_BLACK);
        tft.print("  WLAN");
        
        // No IP address
        tft.setTextColor(TFT_BLUE, TFT_BLACK);
        tft.setCursor(228, MESSAGE_HEIGHT + 7);
        tft.print("---.---.---.---");              
    }

    // DAPNET
    tft.setCursor(47, MESSAGE_HEIGHT + 7);

    if( dapnetConnected )
    {
        tft.setTextColor(TFT_GREEN, TFT_BLACK);
        tft.print("* DAPNET");
    }
    else
    {
        tft.setTextColor(TFT_RED, TFT_BLACK);
        tft.print("  DAPNET");
    }

    // Whitelist
    tft.setTextColor(TFT_YELLOW, TFT_BLACK);
    tft.setCursor(110, MESSAGE_HEIGHT + 7);
    tft.printf("%02u RICs", whitelistCount);

    // Clock
    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.setCursor(170, MESSAGE_HEIGHT + 7);
    tft.print(clockString);
 
}

void DisplayManager::drawMessages()
{
    tft.fillRect(0, 24, DISPLAY_WIDTH, MESSAGE_HEIGHT - 26, TFT_BLACK);

    // No messages available
    if( messageCount == 0 )
    {
        tft.drawFastHLine(0, MESSAGE_HEIGHT - 1, DISPLAY_WIDTH, TFT_WHITE);
        return;
    }

    // Calculate available lines
    // Find out which messages will fit the screen
    const uint16_t availablePixels = MESSAGE_HEIGHT - 40;
    int firstVisible = messageCount - 1;
    uint16_t usedPixels = 0;
    
    for( int i = messageCount - 1; i >= 0; i-- )
    {
        uint16_t neededPixels = getMessageHeight(messages[i]);
        
        if( usedPixels + neededPixels > availablePixels )
        {
            break;
        }
    
        usedPixels += neededPixels;
        firstVisible = i;
    }
    
    // Draw
    int y = 28;
    tft.setTextSize(1);

    for( int i = firstVisible; i < messageCount; i++)
    {
        // Header
        tft.setTextColor(TFT_CYAN, TFT_BLACK);
        tft.setCursor(2, y);

        if( messages[i].name.length() )
        {
            tft.printf("RIC: %s (%lu) FUNC: %u", messages[i].name.c_str(), messages[i].ric, messages[i].function);
        }
        else
        {
            tft.printf("RIC: %lu FUNC: %u", messages[i].ric, messages[i].function);
        }
       
        y += 10;

        // Text
        tft.setTextColor(TFT_WHITE, TFT_BLACK);

        String txt = messages[i].text;
        uint16_t pos = 0;

        while( pos < txt.length() )
        {
            uint16_t endPos = pos + MAX_TEXT_LEN;

            if( endPos > txt.length() )
            {
                endPos = txt.length();
            }

            String part = txt.substring(pos, endPos);

            tft.setCursor(6, y);
            tft.println(part);
            y += 10;
            pos += MAX_TEXT_LEN;
        }

        // Empty lines between messages
        y += 2;
    }

    // Separator to status

    tft.drawFastHLine(0, MESSAGE_HEIGHT - 1, DISPLAY_WIDTH, TFT_WHITE);
    
}

void DisplayManager::setWhitelistCount(uint8_t count)
{
    if( whitelistCount == count )
    {
        return;
    }

    Serial.printf("WhitelistCount = %u\n", count);
    whitelistCount = count;
    statusDirty = true;
    
}
